def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    if opp_c == 0:
        return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'C':
        return 'C'

    opp_def_run = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            opp_def_run += 1
        else:
            break

    if opp_def_run >= 3:
        return 'C'

    recent_len = min(5, n)
    recent_opp = opp[-recent_len:]
    recent_c = sum(1 for a in recent_opp if a == 'C')
    recent_ratio = recent_c / recent_len

    if recent_ratio >= 0.6:
        return 'C'

    dd_run = 0
    for i in range(n-1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    if dd_run >= 2:
        return 'C'

    return 'D'
